mkuse!{use rustc_index :: IndexVec ;}
mkuse!{use rustc_middle :: mir :: visit :: { PlaceContext , Visitor } ;}
mkuse!{use rustc_middle :: mir :: { Body , Local , Location } ;}
mkuse!{use rustc_mir_dataflow :: points :: { DenseLocationMap , PointIndex } ;}
mkuse!{use crate :: def_use :: { self , DefUse } ;}
mkitem!{mkstruct!{# [doc = " A map that cross references each local with the locations where it"] # [doc = " is defined (assigned), used, or dropped. Used during liveness"] # [doc = " computation."] # [doc = ""] # [doc = " We keep track only of `Local`s we'll do the liveness analysis later,"] # [doc = " this means that our internal `IndexVec`s will only be sparsely populated."] # [doc = " In the time-memory trade-off between keeping compact vectors with new"] # [doc = " indexes (and needing to continuously map the `Local` index to its compact"] # [doc = " counterpart) and having `IndexVec`s that we only use a fraction of, time"] # [doc = " (and code simplicity) was favored. The rationale is that we only keep"] # [doc = " a small number of `IndexVec`s throughout the entire analysis while, in"] # [doc = " contrast, we're accessing each `Local` *many* times."] pub (crate) struct LocalUseMap { # [doc = " Head of a linked list of **definitions** of each variable --"] # [doc = " definition in this context means assignment, e.g., `x` is"] # [doc = " defined in `x = y` but not `y`; that first def is the head of"] # [doc = " a linked list that lets you enumerate all places the variable"] # [doc = " is assigned."] first_def_at : IndexVec < Local , Option < AppearanceIndex > > , # [doc = " Head of a linked list of **uses** of each variable -- use in"] # [doc = " this context means that the existing value of the variable is"] # [doc = " read or modified. e.g., `y` is used in `x = y` but not `x`."] # [doc = " Note that `DROP(x)` terminators are excluded from this list."] first_use_at : IndexVec < Local , Option < AppearanceIndex > > , # [doc = " Head of a linked list of **drops** of each variable -- these"] # [doc = " are a special category of uses corresponding to the drop that"] # [doc = " we add for each local variable."] first_drop_at : IndexVec < Local , Option < AppearanceIndex > > , appearances : Appearances , }}}
mkitem!{type Appearances = IndexVec < AppearanceIndex , Appearance > ;}
mkitem!{mkstruct!{struct Appearance { point_index : PointIndex , next : Option < AppearanceIndex > , }}}
mkitem!{rustc_index :: newtype_index ! { pub struct AppearanceIndex { } }}

macro_rules! appearances_iter_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function appearances_iter in module {}", module_path!());
    };
}

mkfn!{
    appearances_iter_introspect!();
    fn appearances_iter (first : Option < AppearanceIndex > , appearances : & Appearances ,) -> impl Iterator < Item = AppearanceIndex > { AppearancesIter { appearances , current : first } }
}
mkitem!{mkstruct!{struct AppearancesIter < 'a > { appearances : & 'a Appearances , current : Option < AppearanceIndex > , }}}
mkitem!{mkimpl!{impl < 'a > Iterator for AppearancesIter < 'a > { type Item = AppearanceIndex ; fn next (& mut self) -> Option < AppearanceIndex > { if let Some (c) = self . current { self . current = self . appearances [c] . next ; Some (c) } else { None } } }}}
mkitem!{mkimpl!{impl LocalUseMap { pub (crate) fn build (live_locals : & [Local] , location_map : & DenseLocationMap , body : & Body < '_ > ,) -> Self { let nones = IndexVec :: from_elem (None , & body . local_decls) ; let mut local_use_map = LocalUseMap { first_def_at : nones . clone () , first_use_at : nones . clone () , first_drop_at : nones , appearances : IndexVec :: new () , } ; if live_locals . is_empty () { return local_use_map ; } let mut locals_with_use_data : IndexVec < Local , bool > = IndexVec :: from_elem (false , & body . local_decls) ; live_locals . iter () . for_each (| & local | locals_with_use_data [local] = true) ; LocalUseMapBuild { local_use_map : & mut local_use_map , location_map , locals_with_use_data } . visit_body (body) ; local_use_map } pub (crate) fn defs (& self , local : Local) -> impl Iterator < Item = PointIndex > { appearances_iter (self . first_def_at [local] , & self . appearances) . map (move | aa | self . appearances [aa] . point_index) } pub (crate) fn uses (& self , local : Local) -> impl Iterator < Item = PointIndex > { appearances_iter (self . first_use_at [local] , & self . appearances) . map (move | aa | self . appearances [aa] . point_index) } pub (crate) fn drops (& self , local : Local) -> impl Iterator < Item = PointIndex > { appearances_iter (self . first_drop_at [local] , & self . appearances) . map (move | aa | self . appearances [aa] . point_index) } }}}
mkitem!{mkstruct!{struct LocalUseMapBuild < 'me > { local_use_map : & 'me mut LocalUseMap , location_map : & 'me DenseLocationMap , locals_with_use_data : IndexVec < Local , bool > , }}}
mkitem!{mkimpl!{impl Visitor < '_ > for LocalUseMapBuild < '_ > { fn visit_local (& mut self , local : Local , context : PlaceContext , location : Location) { if self . locals_with_use_data [local] && let Some (def_use) = def_use :: categorize (context) { let first_appearance = match def_use { DefUse :: Def => & mut self . local_use_map . first_def_at [local] , DefUse :: Use => & mut self . local_use_map . first_use_at [local] , DefUse :: Drop => & mut self . local_use_map . first_drop_at [local] , } ; let point_index = self . location_map . point_from_location (location) ; let appearance_index = self . local_use_map . appearances . push (Appearance { point_index , next : * first_appearance }) ; * first_appearance = Some (appearance_index) ; } } }}}